import { beforeAll, describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { loadValidatedSkillMap } from "../src/shared/skill-map-loader.ts";

// Content-contract guards for the vercel-agent skill: pricing and surface area
// track vercel.com/docs/agent and /docs/agent/pricing.

const ROOT = resolve(import.meta.dirname, "..");
const SKILL_PATH = resolve(ROOT, "skills/vercel-agent/SKILL.md");

let skill: string;

beforeAll(() => {
  const { skills } = loadValidatedSkillMap(resolve(ROOT, "skills"));
  expect(skills["vercel-agent"]).toBeDefined();
  skill = readFileSync(SKILL_PATH, "utf8");
});

describe("vercel-agent guidance", () => {
  test("states the documented token-rate pricing, not retired flat fees", () => {
    expect(skill).toContain("$0.25 per million");
    expect(skill).toContain("10 investigations per billing cycle");
    expect(skill).not.toMatch(/\$0\.30 per Code Review/);
    expect(skill).not.toMatch(/\$100 promotional credit/);
  });

  test("covers chat and approved actions alongside review and investigation", () => {
    expect(skill).toContain("### Chat");
    expect(skill).toMatch(/Slack/);
    expect(skill).toContain("read-only by default");
    expect(skill).toContain("https://vercel.com/docs/agent/pricing");
  });
});

import { beforeAll, describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { loadValidatedSkillMap } from "../src/shared/skill-map-loader.ts";

// Content-contract guards for the vercel-storage skill's Blob guidance. The
// private-read API is easy to get wrong (it takes a pathname plus a required
// `access` option and returns a result object, not a stream), and the product
// status matters because agents copy it verbatim.

const ROOT = resolve(import.meta.dirname, "..");
const SKILL_PATH = resolve(ROOT, "skills/vercel-storage/SKILL.md");

let skill: string;

beforeAll(() => {
  const { skills } = loadValidatedSkillMap(resolve(ROOT, "skills"));
  expect(skills["vercel-storage"]).toBeDefined();
  skill = readFileSync(SKILL_PATH, "utf8");
});

describe("vercel-storage Blob guidance", () => {
  test("reads private blobs by pathname with a required access option", () => {
    expect(skill).toContain("await get('docs/secret.pdf', { access: 'private' })");
    expect(skill).toContain("privateFile?.statusCode === 200");
    expect(skill).not.toMatch(/get\(privateBlob\.url\)/);
    // Every Blob get() call passes the required `access` option, including
    // brace-less calls like `get(blob.url)` that the old text used. Scope to
    // the @vercel/blob code block so Global Config's get(key) is not counted.
    const blobBlock = skill.match(/```ts\nimport \{ put, del, list, get \} from '@vercel\/blob'[\s\S]*?\n```/)?.[0];
    expect(blobBlock).toBeDefined();
    const getCalls = blobBlock!.match(/await get\([\s\S]*?\)\n/g) ?? [];
    expect(getCalls.length).toBeGreaterThanOrEqual(2);
    for (const call of getCalls) {
      expect(call).toMatch(/access:\s*'(private|public)'/);
    }
  });

  test("describes Private Storage as generally available with OIDC by default", () => {
    expect(skill).toContain("**Private Storage** (generally available)");
    expect(skill).not.toContain("**Private Storage** (public beta)");
    expect(skill).toContain("vercel blob create-store <name> --access private");
    expect(skill).toContain("BLOB_STORE_ID");
    expect(skill).toContain("presignUrl()");
  });
});

/**
 * Focused tests for redactCommand() in hooks/pretooluse-skill-inject.mjs.
 *
 * Covers: env-var key preservation, bearer tokens, connection strings,
 * JSON secret values, URL query params, cookies, CLI flags, truncation,
 * and edge cases.
 */

import { describe, test, expect, beforeAll } from "bun:test";

let redactCommand: (cmd: string) => string;

beforeAll(async () => {
  const mod = await import("../hooks/pretooluse-skill-inject.mjs");
  redactCommand = mod.redactCommand;
});

// ---------------------------------------------------------------------------
// Env-var style: KEY=value
// ---------------------------------------------------------------------------

describe("env-var key=value redaction", () => {
  test("preserves full prefixed key name (regression: key-loss bug)", () => {
    expect(redactCommand("VERCEL_TOKEN=abc123")).toBe("VERCEL_TOKEN=[REDACTED]");
    expect(redactCommand("MY_API_KEY=secret")).toBe("MY_API_KEY=[REDACTED]");
    expect(redactCommand("APP_SECRET=s3cret")).toBe("APP_SECRET=[REDACTED]");
    expect(redactCommand("DB_PASSWORD=hunter2 npm start")).toBe("DB_PASSWORD=[REDACTED] npm start");
  });

  test("simple keys without prefix", () => {
    expect(redactCommand("TOKEN=abc123")).toBe("TOKEN=[REDACTED]");
    expect(redactCommand("KEY=abc123")).toBe("KEY=[REDACTED]");
    expect(redactCommand("SECRET=abc123")).toBe("SECRET=[REDACTED]");
  });

  test("sensitive word in the middle of key name", () => {
    expect(redactCommand("MY_SECRET_VALUE=hunter2")).toBe("MY_SECRET_VALUE=[REDACTED]");
    expect(redactCommand("CREDENTIAL_STORE=val")).toBe("CREDENTIAL_STORE=[REDACTED]");
    expect(redactCommand("MY_TOKEN_ID=abc")).toBe("MY_TOKEN_ID=[REDACTED]");
  });

  test("case-insensitive matching", () => {
    expect(redactCommand("token=abc123")).toContain("[REDACTED]");
    expect(redactCommand("Token=abc123")).toContain("[REDACTED]");
  });

  test("multiple env vars in one command", () => {
    const result = redactCommand("TOKEN=aaa KEY=bbb SECRET=ccc");
    expect(result).not.toContain("aaa");
    expect(result).not.toContain("bbb");
    expect(result).not.toContain("ccc");
  });
});

// ---------------------------------------------------------------------------
// Bearer / token authorization
// ---------------------------------------------------------------------------

describe("bearer and token authorization", () => {
  test("masks Bearer tokens", () => {
    const result = redactCommand("curl -H 'Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.abc'");
    expect(result).toContain("Bearer [REDACTED]");
    expect(result).not.toContain("eyJhbGciOiJIUzI1NiJ9");
  });

  test("masks 'token xxx' authorization style", () => {
    const result = redactCommand("gh api -H 'Authorization: token ghp_abc123XYZ456'");
    expect(result).toContain("token [REDACTED]");
    expect(result).not.toContain("ghp_abc123XYZ456");
  });
});

// ---------------------------------------------------------------------------
// Connection strings
// ---------------------------------------------------------------------------

describe("connection strings", () => {
  test("masks postgres connection string credentials", () => {
    const result = redactCommand("psql postgres://admin:s3cret@db.example.com:5432/mydb");
    expect(result).toContain("postgres://[REDACTED]@db.example.com");
    expect(result).not.toContain("s3cret");
    expect(result).not.toContain("admin:");
  });

  test("masks redis connection string credentials", () => {
    const result = redactCommand("redis-cli -u redis://default:hunter2@cache.example.com:6379");
    expect(result).toContain("redis://[REDACTED]@cache.example.com");
    expect(result).not.toContain("hunter2");
  });

  test("masks mysql connection string credentials", () => {
    const result = redactCommand("mysql mysql://root:pass123@localhost:3306/db");
    expect(result).toContain("mysql://[REDACTED]@localhost");
    expect(result).not.toContain("pass123");
  });
});

// ---------------------------------------------------------------------------
// JSON secret values
// ---------------------------------------------------------------------------

describe("JSON secret values", () => {
  test("masks token in JSON", () => {
    const result = redactCommand('echo \'{"token": "sk_live_abc123", "name": "test"}\'');
    expect(result).toContain('"token": "[REDACTED]"');
    expect(result).not.toContain("sk_live_abc123");
    // Non-sensitive keys preserved
    expect(result).toContain('"name": "test"');
  });

  test("masks password and api_key in JSON", () => {
    expect(redactCommand('{"password": "hunter2"}')).toContain('"password": "[REDACTED]"');
    expect(redactCommand('{"api_key": "ak_xyz"}')).toContain('"api_key": "[REDACTED]"');
    expect(redactCommand('{"apiKey": "ak_xyz"}')).toContain('"apiKey": "[REDACTED]"');
  });

  test("masks secret and credential in JSON", () => {
    expect(redactCommand('{"secret": "s3cret"}')).toContain('"secret": "[REDACTED]"');
    expect(redactCommand('{"credential": "cred123"}')).toContain('"credential": "[REDACTED]"');
  });
});

// ---------------------------------------------------------------------------
// URL query parameters
// ---------------------------------------------------------------------------

describe("URL query param redaction", () => {
  test("masks single sensitive query param", () => {
    const result = redactCommand("curl 'https://x.co?token=abc123&name=foo'");
    expect(result).toContain("?token=[REDACTED]");
    expect(result).not.toContain("abc123");
    expect(result).toContain("&name=foo");
  });

  test("masks multiple sensitive query params", () => {
    const result = redactCommand("curl 'https://x.co?key=k1&secret=s2&page=1'");
    expect(result).toContain("?key=[REDACTED]");
    expect(result).toContain("&secret=[REDACTED]");
    expect(result).toContain("&page=1");
  });
});

// ---------------------------------------------------------------------------
// Cookie headers
// ---------------------------------------------------------------------------

describe("cookie header redaction", () => {
  test("masks Cookie header values", () => {
    const result = redactCommand("curl -H 'Cookie: session=abc123; auth_tok=xyz789' https://example.com");
    expect(result).toContain("Cookie: [REDACTED]");
    expect(result).not.toContain("abc123");
    expect(result).not.toContain("xyz789");
  });

  test("masks Set-Cookie header values", () => {
    const result = redactCommand("curl -v 'Set-Cookie: id=a3fWa; Path=/; HttpOnly'");
    expect(result).toContain("Set-Cookie: [REDACTED]");
    expect(result).not.toContain("a3fWa");
  });
});

// ---------------------------------------------------------------------------
// CLI flag redaction (--token, --password, --api-key, --secret, --auth)
// ---------------------------------------------------------------------------

describe("CLI flag redaction", () => {
  test("masks --token flag value", () => {
    const result = redactCommand("vercel --token tk_abcdef deploy");
    expect(result).toContain("--token [REDACTED]");
    expect(result).not.toContain("tk_abcdef");
  });

  test("masks --password flag value", () => {
    const result = redactCommand("mysql --password s3cret -u root");
    expect(result).toContain("--password [REDACTED]");
    expect(result).not.toContain("s3cret");
  });

  test("masks --api-key flag value", () => {
    const result = redactCommand("cli --api-key my-key-123");
    expect(result).toContain("--api-key [REDACTED]");
    expect(result).not.toContain("my-key-123");
  });

  test("masks --secret and --auth flags", () => {
    expect(redactCommand("tool --secret mysecretval")).toContain("--secret [REDACTED]");
    expect(redactCommand("tool --auth bearer_tok")).toContain("--auth [REDACTED]");
  });

  test("masks --credential flag value", () => {
    expect(redactCommand("tool --credential cred123")).toContain("--credential [REDACTED]");
    expect(redactCommand("tool --credential cred123")).not.toContain("cred123");
  });
});

// ---------------------------------------------------------------------------
// Truncation
// ---------------------------------------------------------------------------

describe("truncation", () => {
  test("truncates commands longer than 200 chars", () => {
    const longCmd = "a".repeat(300);
    const result = redactCommand(longCmd);
    expect(result.length).toBeLessThan(300);
    expect(result).toContain("…[truncated]");
    expect(result.startsWith("a".repeat(200))).toBe(true);
  });

  test("does not truncate commands under 200 chars", () => {
    const cmd = "a".repeat(100);
    expect(redactCommand(cmd)).toBe(cmd);
  });
});

// ---------------------------------------------------------------------------
// Edge cases
// ---------------------------------------------------------------------------

describe("edge cases", () => {
  test("handles non-string input gracefully", () => {
    expect(redactCommand(undefined as any)).toBe("");
    expect(redactCommand(null as any)).toBe("");
    expect(redactCommand(123 as any)).toBe("");
  });

  test("returns empty string for empty input", () => {
    expect(redactCommand("")).toBe("");
  });

  test("preserves safe commands unchanged", () => {
    expect(redactCommand("ls -la")).toBe("ls -la");
    expect(redactCommand("git status")).toBe("git status");
    expect(redactCommand("npm install express")).toBe("npm install express");
  });

  test("combined redaction: multiple pattern types in one command", () => {
    const cmd = "VERCEL_TOKEN=abc curl -H 'Authorization: Bearer eyJhbGciOiJI' --password s3cret https://x.co?key=k1";
    const result = redactCommand(cmd);
    expect(result).toContain("VERCEL_TOKEN=[REDACTED]");
    expect(result).toContain("Bearer [REDACTED]");
    expect(result).toContain("--password [REDACTED]");
    expect(result).toContain("?key=[REDACTED]");
    expect(result).not.toContain("abc ");
    expect(result).not.toContain("eyJhbGciOiJI");
    expect(result).not.toContain("s3cret");
    expect(result).not.toContain("k1");
  });
});

import { beforeAll, describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import {
  compileSkillPatterns,
  matchBashWithReason,
  matchPathWithReason,
  type CompiledSkillEntry,
} from "../hooks/src/patterns.mts";
import { loadValidatedSkillMap } from "../src/shared/skill-map-loader.ts";

// The auth skill's Next.js examples must use the Next.js 16 proxy.ts
// convention (the routing-middleware skill tells users to migrate off
// middleware.ts), and the skill must activate for proxy.ts files.

const ROOT = resolve(import.meta.dirname, "..");
const AUTH_SKILL = resolve(ROOT, "skills/auth/SKILL.md");
const ENV_SKILL = resolve(ROOT, "skills/env-vars/SKILL.md");
const BOOTSTRAP_SKILL = resolve(ROOT, "skills/bootstrap/SKILL.md");

let compiledAuth: CompiledSkillEntry;
let auth: string;
let envVars: string;
let bootstrap: string;

beforeAll(() => {
  const { skills } = loadValidatedSkillMap(resolve(ROOT, "skills"));
  expect(skills["auth"]).toBeDefined();
  compiledAuth = compileSkillPatterns({ auth: skills["auth"] })[0];
  auth = readFileSync(AUTH_SKILL, "utf8");
  envVars = readFileSync(ENV_SKILL, "utf8");
  bootstrap = readFileSync(BOOTSTRAP_SKILL, "utf8");
});

describe("auth skill activation", () => {
  test.each(["proxy.ts", "src/proxy.ts", "middleware.ts", "auth.ts"])(
    "matches %s",
    (path) => {
      expect(matchPathWithReason(path, compiledAuth.compiledPaths)).not.toBeNull();
    },
  );

  test.each(["npm install @vercel/kms", "pnpm add @vercel/kms jose", "bun add @vercel/kms"])(
    "matches KMS install: %s",
    (command) => {
      expect(matchBashWithReason(command, compiledAuth.compiledBash)).not.toBeNull();
    },
  );
});

describe("auth skill guidance", () => {
  test("Next.js interception examples use proxy.ts with a proxy export", () => {
    expect(auth).not.toMatch(/^\/\/ middleware\.ts/m);
    expect(auth).not.toMatch(/export (default )?(async )?function middleware\b/);
    expect(auth).toContain("export async function proxy(request: NextRequest)");
    expect(auth).toMatch(/^\/\/ proxy\.ts/m);
  });

  test("covers Vercel's own identity primitives", () => {
    expect(auth).toContain("### Sign in with Vercel");
    expect(auth).toContain("### Vercel Passport");
    expect(auth).toContain("### Vercel KMS");
    expect(auth).toContain("https://kms.vercel.com/<issuerId>/jwks.json");
    expect(auth).toContain("code_challenge_method: 'S256'");
  });
});

describe("env-vars skill guidance", () => {
  test("does not combine development with production/preview in one vercel env add", () => {
    const commandLines = [envVars, bootstrap]
      .flatMap((text) => text.split("\n"))
      // command lines only (optionally piped), not prose
      .filter((line) => /^\s*(\S.*\| )?vercel env add\b/.test(line));
    expect(commandLines.length).toBeGreaterThanOrEqual(5);
    for (const line of commandLines) {
      const command = line.replace(/\s#.*$/, ""); // ignore trailing shell comments
      const targets = command.match(/\b(production|preview|development)\b/g) ?? [];
      const mixesDev = targets.includes("development") && targets.length > 1;
      expect(mixesDev).toBe(false);
    }
  });

  test("never pipes a secret value through echo", () => {
    // echo puts the value in shell history and process arguments; the skill
    // must read secrets from a file (or a variable via printf) instead.
    expect(envVars).not.toMatch(/echo "[^"]*secret[^"]*" \| vercel env (add|update)/i);
    expect(envVars).toContain("vercel env add MY_SECRET production < ./secret.txt");
  });

  test("documents Secret and Config types, their flags, and the update command", () => {
    expect(envVars).toContain("--type secret");
    expect(envVars).toContain("--type config");
    expect(envVars).toContain("--no-sensitive");
    expect(envVars).toContain("Separate Production Secret Values");
    expect(envVars).toMatch(/stored as Secret/);
    expect(envVars).toContain("vercel env update MY_SECRET production");
  });
});

import { beforeAll, describe, expect, test } from "bun:test";
import { resolve } from "node:path";
import {
  compilePromptSignals,
  matchPromptWithReason,
  normalizePromptText,
  type CompiledPromptSignals,
} from "../hooks/src/prompt-patterns.mts";
import {
  compileSkillPatterns,
  matchBashWithReason,
  type CompiledSkillEntry,
} from "../hooks/src/patterns.mts";
import { analyzePrompt } from "../hooks/src/prompt-analysis.mts";
import { loadValidatedSkillMap } from "../src/shared/skill-map-loader.ts";

const ROOT = resolve(import.meta.dirname, "..");

let compiledPromptSignals: CompiledPromptSignals;
let compiledSkill: CompiledSkillEntry;
let skillMap: Record<string, any>;

beforeAll(() => {
  const loaded = loadValidatedSkillMap(resolve(ROOT, "skills"));
  skillMap = loaded.skills;

  const buildAgents = skillMap["build-agents"];
  const eve = skillMap.eve;

  expect(buildAgents).toBeDefined();
  expect(buildAgents.promptSignals).toBeDefined();
  expect(eve).toBeDefined();
  expect(buildAgents.priority).toBeGreaterThan(eve.priority);

  compiledPromptSignals = compilePromptSignals(buildAgents.promptSignals!);
  compiledSkill = compileSkillPatterns({ "build-agents": buildAgents })[0];
});

function matchesPrompt(prompt: string): boolean {
  return matchPromptWithReason(
    normalizePromptText(prompt),
    compiledPromptSignals,
  ).matched;
}

describe("build-agents prompt activation", () => {
  test.each([
    "Build me an agent that triages support tickets.",
    "Create an agent that runs scheduled research reports.",
    "Scaffold a Slack agent that answers channel questions.",
    "Design a multi-agent system with tools and approvals.",
    "Which agent framework should I use for this application?",
    "Implement a tool-calling agent for release-note triage.",
  ])("matches generic agent-building intent: %s", (prompt) => {
    expect(matchesPrompt(prompt)).toBe(true);
  });

  test.each([
    "Build a browser user-agent parser.",
    "Configure Vercel Agent code review for this repo.",
    "Investigate an incident with Vercel Agent.",
    "Tell me about EVE Online agents.",
  ])("does not match unrelated agent wording: %s", (prompt) => {
    expect(matchesPrompt(prompt)).toBe(false);
  });

  test("is the top prompt-analysis match for a generic agent build", () => {
    const report = analyzePrompt(
      "build me an agent",
      skillMap,
      "",
      8_000,
      2,
      { lexicalEnabled: false },
    );

    expect(report.selectedSkills[0]).toBe("build-agents");
    expect(report.perSkillResults["build-agents"].matched).toBe(true);
    expect(report.perSkillResults.eve.matched).toBe(false);
  });

  test("matches new eve agent scaffold commands", () => {
    expect(matchBashWithReason("npx eve@latest init support-agent", compiledSkill.compiledBash)).not.toBeNull();
    expect(matchBashWithReason("bunx eve init research-agent", compiledSkill.compiledBash)).not.toBeNull();
    expect(matchBashWithReason("eve dev", compiledSkill.compiledBash)).toBeNull();
  });
});

import { describe, test, expect, beforeEach, afterEach } from "bun:test";
import { writeFileSync, readdirSync, rmSync } from "node:fs";
import { join, resolve } from "node:path";
import { tmpdir } from "node:os";

const ROOT = resolve(import.meta.dirname, "..");
const HOOK_SCRIPT = join(ROOT, "hooks", "pretooluse-skill-inject.mjs");
const UNLIMITED_BUDGET = "999999";
let testSession: string;

const EXPECTED_SLACK_ROUTE_SKILLS = ["chat-sdk", "vercel-functions"] as const;

function seedSeenSkills(skills: string[], session?: string): void {
  const sid = session ?? testSession;
  writeFileSync(join(tmpdir(), `vercel-plugin-${sid}-seen-skills.txt`), skills.join(","), "utf-8");
}

function cleanupSessionDedup(session?: string): void {
  const prefix = `vercel-plugin-${session ?? testSession}-`;
  try {
    for (const entry of readdirSync(tmpdir())) {
      if (entry.startsWith(prefix)) {
        rmSync(join(tmpdir(), entry), { recursive: true, force: true });
      }
    }
  } catch {}
}

beforeEach(() => {
  testSession = `subagent-${Date.now()}-${Math.random().toString(36).slice(2)}`;
});

afterEach(() => {
  cleanupSessionDedup();
});

async function runHookEnv(
  input: { tool_name: string; tool_input: Record<string, string> },
  env: Record<string, string | undefined>,
  opts?: { omitSessionId?: boolean; omitSeenSkillsEnv?: boolean },
): Promise<{ code: number; stdout: string; stderr: string }> {
  const payload = opts?.omitSessionId
    ? JSON.stringify(input)
    : JSON.stringify({ ...input, session_id: testSession });
  const childEnv: Record<string, string | undefined> = {
    ...process.env,
    VERCEL_PLUGIN_INJECTION_BUDGET: UNLIMITED_BUDGET,
    ...env,
  };
  delete childEnv.VERCEL_PLUGIN_SEEN_SKILLS;
  const proc = Bun.spawn(["node", HOOK_SCRIPT], {
    stdin: "pipe",
    stdout: "pipe",
    stderr: "pipe",
    env: childEnv,
  });
  proc.stdin.write(payload);
  proc.stdin.end();
  const code = await proc.exited;
  const stdout = await new Response(proc.stdout).text();
  const stderr = await new Response(proc.stderr).text();
  return { code, stdout, stderr };
}

function parseInjectedSkills(stdout: string): string[] {
  const parsed = JSON.parse(stdout);
  const ctx = parsed?.hookSpecificOutput?.additionalContext || "";
  const match = ctx.match(/<!-- skillInjection: (\{.*?\}) -->/);
  const si = match ? JSON.parse(match[1]) : {};
  const injectedSkills = si.injectedSkills;
  return Array.isArray(injectedSkills) ? injectedSkills : [];
}

function parseDebugLines(stderr: string): Array<Record<string, unknown>> {
  return stderr
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as Record<string, unknown>);
}

describe("subagent fresh env dedup behavior", () => {
  const slackRoutePath = "/Users/me/slack-clone/app/api/slack/route.ts";

  test("fresh subagent without inherited seen-skills re-injects the same skills as the lead agent", async () => {
    // Lead agent injects skills
    const { code: leadCode, stdout: leadStdout } = await runHookEnv(
      { tool_name: "Read", tool_input: { file_path: slackRoutePath } },
      { VERCEL_PLUGIN_HOOK_DEBUG: "1" },
    );

    expect(leadCode).toBe(0);
    const leadInjected = parseInjectedSkills(leadStdout);
    expect(leadInjected).toEqual(EXPECTED_SLACK_ROUTE_SKILLS);

    // Second call with file-based dedup — should be deduped
    seedSeenSkills(leadInjected);
    const { code: leadSecondCode, stdout: leadSecondStdout } = await runHookEnv(
      { tool_name: "Read", tool_input: { file_path: slackRoutePath } },
      {},
    );

    expect(leadSecondCode).toBe(0);
    expect(JSON.parse(leadSecondStdout)).toEqual({});

    // Fresh subagent with a new session — no dedup state — re-injects
    const leadSession = testSession;
    const subagentSession = `subagent-child-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    testSession = subagentSession;
    let subagentResult: { code: number; stdout: string; stderr: string };
    try {
      subagentResult = await runHookEnv(
        { tool_name: "Read", tool_input: { file_path: slackRoutePath } },
